#include <bits/stdc++.h>
#define reg register
#define int long long
using namespace std;

inline int read() {
    int sign=1, result=0; char ch=getchar();
    while (ch<'0'||ch>'9') { if (ch=='-') sign=-1; ch=getchar(); }
    while (ch>='0'&&ch<='9') { result=result*10+ch-48; ch=getchar(); }
    return sign*result;
}

inline int min_val(reg int x, reg int y) { return x<y?x:y; }
inline int max_val(reg int x, reg int y) { return x>y?x:y; }

const int MAXN=2000010, MOD1=1000000007, MOD2=998244353, BASE=1000000;
int total_numbers, current_index, total_answer, prefix_sum[10];
vector<int> digit_vectors[10];

inline int mod_value(reg int x) { return (x%MOD2+MOD2)%MOD2; }

void generate_sequence(reg int start, reg int depth) {
    ++current_index;
    digit_vectors[depth].push_back(mod_value(current_index - start));
    (prefix_sum[depth] += digit_vectors[depth].back()) %= MOD1;
    if (depth==6) return;
    for (reg int digit=0; digit<10; digit++) generate_sequence(start*10+digit, depth+1);
}

void process_sequence(reg int number) {
    if (number > n) return;
    if (number*BASE + (BASE-1) <= n && number*BASE*10 > n) {
        reg int prev_idx = current_index;
        for (reg int level=0, multiplier=1; level<=6; level++, multiplier*=10) {
            reg int size=digit_vectors[level].size();
            reg int delta=mod_value(prev_idx - number*multiplier);
            reg int position=lower_bound(digit_vectors[level].begin(), digit_vectors[level].end(), MOD2 - delta) - digit_vectors[level].begin();
            total_answer=(total_answer + delta*size + prefix_sum[level] - MOD2*(size - position))%MOD1;
            current_index+=size;
        }
        return;
    }
    ++current_index;
    total_answer=(total_answer + mod_value(current_index - number))%MOD1;
    for (reg int digit=0; digit<10; digit++) process_sequence(number*10+digit);
}

signed main() {
    n=read();
    generate_sequence(0,0);
    for (reg int i=0; i<=6; i++) sort(digit_vectors[i].begin(), digit_vectors[i].end());
    current_index=0;
    for (reg int i=1; i<=9; i++) process_sequence(i);
    printf("%lld", (total_answer+MOD1)%MOD1);
    return 0;
